<?php
$dealEditId=(int)($dealEditId??0);$pageTitle=$dealEditId?'Edit Deal — RCS Admin':'Add Deal — RCS Admin';$currentAdmPage='deals';include __DIR__.'/layout.php';
?>
<div class="adm-pt"><?= $dealEditId?'Edit Best Deal':'Add Best Deal' ?></div>
<div class="fsec" style="max-width:980px"><div id="dealErr" class="adm-inline-error" hidden></div>
  <div class="f2"><div class="fg"><label>Card Position</label><select class="fi" id="deal-position"><option value="1">Card 1</option><option value="2">Card 2</option><option value="3">Card 3</option><option value="4">Card 4</option><option value="5">Card 5</option></select></div><div class="fg"><label>Deal Content</label><select class="fi" id="deal-type" onchange="renderMode()"><option value="deal">Selected Product</option><option value="promo">Clickable Image</option></select></div></div>
  <section id="productDealFields"><div class="f2"><div class="fg"><label>Category</label><select class="fi" id="deal-category" onchange="renderProducts()"></select></div><div class="fg"><label>Product</label><select class="fi" id="deal-product"></select></div></div></section>
  <section id="promoDealFields" hidden><div class="f2"><div class="fg"><label>Banner Image</label><input class="fi" type="file" id="deal-image" accept="image/jpeg,image/png,image/webp" onchange="uploadImage()"></div><div class="fg"><label>Destination Link</label><input class="fi" id="deal-link" placeholder="/category/visiting-card"></div></div><input type="hidden" id="deal-image-path"><div id="dealImageState" class="adm-muted"></div></section>
  <div class="form-actions"><button class="btn btn-blue" id="saveBtn" onclick="saveDeal()">Save Deal</button><a class="btn btn-outline" href="/admin/deals">Cancel</a></div>
</div>
<script>
const EDIT_ID=<?= $dealEditId ?>,CSRF=<?= json_encode($csrf??'') ?>;let deals=[],categories=[],products=[];
const err=m=>{dealErr.hidden=!m;dealErr.textContent=m||''};
function renderMode(){const promo=dealType()==='promo';productDealFields.hidden=promo;promoDealFields.hidden=!promo;}
function dealType(){return document.getElementById('deal-type').value;}
function renderProducts(){const cid=Number(dealCategory.value);dealProduct.innerHTML=products.filter(p=>Number(p.category_id)===cid).map(p=>`<option value="${p.id}">${p.name}</option>`).join('');}
async function boot(){const data=await fetch('/admin/api/deals').then(r=>r.json());deals=data.deals||[];categories=data.categories||[];products=data.products||[];dealCategory.innerHTML=categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');const d=deals.find(x=>Number(x.id)===EDIT_ID);if(d){dealPosition.value=String(Math.max(1,Math.min(5,Number(d.sort_order||1))));dealTypeEl.value=d.deal_type||'deal';const p=products.find(x=>Number(x.id)===Number(d.product_id));if(p)dealCategory.value=String(p.category_id);renderProducts();if(p)dealProduct.value=String(p.id);dealImagePath.value=d.image_path||'';dealLink.value=d.cta_url||'';}else renderProducts();renderMode();}
const dealPosition=document.getElementById('deal-position'),dealTypeEl=document.getElementById('deal-type'),dealCategory=document.getElementById('deal-category'),dealProduct=document.getElementById('deal-product'),dealImage=document.getElementById('deal-image'),dealImagePath=document.getElementById('deal-image-path'),dealImageState=document.getElementById('dealImageState'),dealLink=document.getElementById('deal-link'),productDealFields=document.getElementById('productDealFields'),promoDealFields=document.getElementById('promoDealFields');
async function uploadImage(){const file=dealImage.files?.[0];if(!file)return;dealImageState.textContent='Uploading…';const fd=new FormData();fd.append('image',file);const data=await fetch('/admin/api/deals/upload',{method:'POST',headers:{'X-CSRF-TOKEN':CSRF},body:fd}).then(r=>r.json());if(!data.ok){err(data.msg||'Upload failed');return;}dealImagePath.value=data.path;dealImageState.textContent='Image uploaded.';}
async function saveDeal(){const type=dealType();let payload={deal_type:type,card_position:Number(dealPosition.value||1)};if(type==='deal'){const p=products.find(x=>Number(x.id)===Number(dealProduct.value));if(!p){err('Select a product.');return;}const regular=Number(p.original_price||0),price=Number(p.min_price||0);payload={...payload,product_id:Number(p.id),title:p.name,image_path:p.primary_image||p.image_path||'',image_alt:p.name,price_text:'₹'+price.toLocaleString('en-IN'),subtitle:regular>price?`Save ${Math.round((regular-price)/regular*100)}%`:'Best Deal',cta_text:'Order Now',cta_url:'/product/'+p.slug,color_theme:'green'};}else{if(!dealImagePath.value){err('Upload the banner image.');return;}payload={...payload,title:'Promotion',image_path:dealImagePath.value,image_alt:'Special promotion',cta_text:'View Offer',cta_url:dealLink.value.trim()||'/categories',color_theme:'purple'};}const data=await fetch(EDIT_ID?`/admin/api/deals/${EDIT_ID}`:'/admin/api/deals',{method:EDIT_ID?'PUT':'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':CSRF},body:JSON.stringify(payload)}).then(r=>r.json());if(!data.ok){err(data.msg||'Could not save deal');return;}location.href='/admin/deals';}
boot();
</script>
<?php include __DIR__.'/layout-end.php'; ?>
